// External type declarations (referenced from App.cpp)
typedef enum {
    PROVIDER_GOOGLE,
    PROVIDER_GITHUB,
    PROVIDER_APPLE,
    PROVIDER_TEST_GOOGLE,
    PROVIDER_UNKNOWN
} ProviderType;

// JWT error types
typedef enum {
    JWT_ERROR_NONE = 0,
    JWT_ERROR_INVALID_FORMAT = 1,
    JWT_ERROR_EXPIRED = 2,
    JWT_ERROR_INVALID_SIGNATURE = 3,
    JWT_ERROR_INVALID_ISSUER = 4,
    JWT_ERROR_INVALID_AUDIENCE = 5,
    JWT_ERROR_MISSING_KEY = 6,
    JWT_ERROR_NETWORK = 7,
    JWT_ERROR_NOT_SUPPORTED = 8,
    JWT_ERROR_UNKNOWN_PROVIDER = 9,
    JWT_ERROR = 10
} JWTErrorType;

// JWKS related structures
typedef struct {
    char* kid;
    char* n;  // modulus
    char* e;  // exponent
    char* alg;
    char* kty;
    char* use;
} JWKKey;

typedef struct {
    JWKKey* keys;
    int key_count;
} JWKSResponse;

// JWT processing result structure
typedef struct {
    char* salt_result;
    int error_type;
    const char* error_message;
} JWTProcessResult;

// Provider configuration structure
typedef struct {
    const char* name;
    const char* jwks_url;
    const char* issuer;
    const char* audience;
} ProviderConfig;

// HTTP response structure
struct HTTPResponse {
    char* data;
    size_t size;
};

