    if (test_newly_exposed_functions() != 0) failed_tests++;
    
    // Test BIGNUM error path
    if (test_bignum_error_path() != 0) failed_tests++;
    
    // Test RSA error path
    if (test_rsa_error_path() != 0) failed_tests++;
    
    // Test RSA set key error path
    if (test_rsa_set_key_error() != 0) failed_tests++;
    
    // Test BIO error path
    if (test_bio_error_path() != 0) failed_tests++;
    
