    if (test_pem_write_error() != 0) failed_tests++;
    
    // Test base64 decode error path
    if (test_base64_decode_error() != 0) failed_tests++;
    
    // Test JWKS malloc error path
    if (test_jwks_malloc_error() != 0) failed_tests++;
    
