// Test Base64 decoding edge cases
int test_base64_edge_cases() {
    printf("[TEST] Testing Base64 edge cases\n");
    
    int failed_tests = 0;
    
    // Test base64url_decode with various edge cases
    printf("[DEBUG] Testing base64url_decode edge cases\n");
    uint8_t output[256];
    int output_len;
    
    // Test with empty string
    output_len = 256;
    int result1 = base64url_decode("", output, &output_len);
    printf("[DEBUG] Empty string result: %d\n", result1);
    if (result1 != 0) {
        printf("[ERROR] Empty string should succeed\n");
        failed_tests++;
    }
    
    // Test with single character (should fail)
    output_len = 256;
    int result2 = base64url_decode("A", output, &output_len);
    printf("[DEBUG] Single char result: %d\n", result2);
    if (result2 == 0) {
        printf("[ERROR] Single character should fail\n");
        failed_tests++;
    }
    
    // Test with padding
    output_len = 256;
    int result6 = base64url_decode("SGVsbG8=", output, &output_len);
    printf("[DEBUG] With padding result: %d, output_len: %d\n", result6, output_len);
    if (result6 != 0) {
        printf("[ERROR] Valid base64 with padding should succeed\n");
        failed_tests++;
    }
    
    // Test with NULL output buffer
    output_len = 256;
    int result9 = base64url_decode("ABCD", NULL, &output_len);
    printf("[DEBUG] NULL output buffer result: %d\n", result9);
    if (result9 == 0) {
        printf("[ERROR] NULL output buffer should fail\n");
        failed_tests++;
    }
    
    // Test with NULL output_len pointer
    int result10 = base64url_decode("ABCD", output, NULL);
    printf("[DEBUG] NULL output_len pointer result: %d\n", result10);
    if (result10 == 0) {
        printf("[ERROR] NULL output_len pointer should fail\n");
        failed_tests++;
    }
    
    
    return failed_tests;
}

