// Main function
int main() {
    printf("=== Starting Test Suite ===\n");
    
    // Initialize CURL for tests that need it
    curl_global_init(CURL_GLOBAL_DEFAULT);
    
    // Skip enclave initialization to avoid segfault
    printf("[INFO] Skipping enclave initialization in test mode\n");
    
    // Run tests
    int test_result = run_all_tests();
    
    // Cleanup
    curl_global_cleanup();
    
    printf("=== Test Suite Complete ===\n");
    return test_result;
}

